import{_ as t,o as h,c as a,a2 as i}from"./chunks/framework.mRCPFc5l.js";const s=JSON.parse('{"title":"Vì sao một bài test không đủ để hiểu một learner","description":"","frontmatter":{},"headers":[],"relativePath":"learner/mot-bai-test-khong-du.md","filePath":"learner/mot-bai-test-khong-du.md"}'),g={name:"learner/mot-bai-test-khong-du.md"};function r(o,n,c,u,e,m){return h(),a("div",null,[...n[0]||(n[0]=[i('<h1 id="vi-sao-mot-bai-test-khong-đu-đe-hieu-mot-learner" tabindex="-1">Vì sao một bài test không đủ để hiểu một learner <a class="header-anchor" href="#vi-sao-mot-bai-test-khong-đu-đe-hieu-mot-learner" aria-label="Permalink to &quot;Vì sao một bài test không đủ để hiểu một learner&quot;">​</a></h1><p>Trên trang này# Vì sao một bài test không đủ để hiểu một learner <a href="#vi-sao-mot-bai-test-khong-đu-đe-hieu-mot-learner">​</a> Một bài kiểm tra là một lát cắt: một buổi, một tâm trạng, một bộ câu hỏi, một cách hỏi. Kết luận về một đứa trẻ thì cần nhiều hơn thế rất nhiều. Điều này không có nghĩa bài test vô dụng. Nó rất hữu ích — như <strong>một</strong> nguồn bằng chứng. Vấn đề nằm ở chỗ nó thường bị dùng như nguồn <em>duy nhất</em>, và kết luận rút ra từ nó được đối xử như sự thật cuối cùng.</p><h2 id="sau-thu-mot-bai-test-khong-phan-biet-đuoc-​" tabindex="-1">Sáu thứ một bài test không phân biệt được <a href="#sau-thu-mot-bai-test-khong-phan-biet-đuoc">​</a> <a class="header-anchor" href="#sau-thu-mot-bai-test-khong-phan-biet-đuoc-​" aria-label="Permalink to &quot;Sáu thứ một bài test không phân biệt được [​](#sau-thu-mot-bai-test-khong-phan-biet-đuoc)&quot;">​</a></h2><p><strong>Không biết, hay quên?</strong> Learner sai câu về phân số. Chưa từng học? Hay từng rất vững nhưng tám tháng chưa dùng tới? Hai tình huống này cần hai xử lý hoàn toàn khác nhau — một cái cần học lại từ đầu, cái kia cần đúng hai câu để đánh thức. Bài test cho ra cùng một kết quả sai. <strong>Không hiểu, hay đọc nhầm đề?</strong> Một learner hiểu bài nhưng đọc sót chữ &quot;không&quot; trong đề sẽ ra kết quả giống hệt một learner không hiểu gì. <strong>Yếu thật, hay hôm đó mệt?</strong> Không có bài test nào biết learner đêm qua ngủ 4 tiếng. <strong>Đúng vì biết, hay đúng vì đoán trúng?</strong> Với câu trắc nghiệm bốn phương án, cứ bốn câu đoán bừa thì trung bình đúng một. Một bài 40 câu có thể chứa 8 câu đúng không mang thông tin gì. <strong>Sai vì hổng phần này, hay hổng phần nền cách đó hai lớp?</strong> Đây là chỗ tốn kém nhất. Bài test chỉ ra triệu chứng; nguyên nhân thường nằm ở nơi khác. <strong>Hiểu, hay chỉ thuộc dạng?</strong> Learner làm đúng 10 câu cùng dạng có thể đã nhận ra khuôn mẫu mà không hiểu nguyên tắc. Đổi cách hỏi là lộ ra ngay.</p><h2 id="ba-tinh-huong-trong-giong-nhau-tren-giay-​" tabindex="-1">Ba tình huống trông giống nhau trên giấy <a href="#ba-tinh-huong-trong-giong-nhau-tren-giay">​</a> <a class="header-anchor" href="#ba-tinh-huong-trong-giong-nhau-tren-giay-​" aria-label="Permalink to &quot;Ba tình huống trông giống nhau trên giấy [​](#ba-tinh-huong-trong-giong-nhau-tren-giay)&quot;">​</a></h2><p>LearnerKết quả bài testSự thậtNên làm gìA3/10Chưa từng học phần nàyHọc từ đầuB3/10Từng đạt 0.9, 8 tháng không dùng2 câu nhớ lại là đủC3/10Hiểu bài, đang ốm, đọc đề vộiKhông làm gì, đo lại tuần sauCả ba đều &quot;3/10&quot;. Xử lý A theo cách của B là bỏ mặc một lỗ hổng thật. Xử lý B theo cách của A là đốt nhiều giờ vào thứ chỉ cần vài phút. Xử lý C theo cách của A hoặc B là làm một đứa trẻ đang ốm phải học lại thứ nó vốn đã biết.</p><h2 id="nemo12-lam-khac-the-nao-​" tabindex="-1">Nemo12 làm khác thế nào <a href="#nemo12-lam-khac-the-nao">​</a> <a class="header-anchor" href="#nemo12-lam-khac-the-nao-​" aria-label="Permalink to &quot;Nemo12 làm khác thế nào [​](#nemo12-lam-khac-the-nao)&quot;">​</a></h2><p><strong>Nhiều nguồn, không phải một.</strong> Bài luyện tập, bài đo, quan sát của mentor, nhận xét của phụ huynh, hành vi trong lúc học — tất cả đều đổ vào cùng một kho bằng chứng, mỗi loại mang trọng số riêng. <strong>Nhiều thời điểm.</strong> Bằng chứng rải theo thời gian. Một buổi tệ hiện ra như một buổi tệ, không phải như một kết luận. <strong>Đo cả cách trả lời, không chỉ đáp án.</strong> Mất bao lâu, có dùng gợi ý không, tự khai chắc chắn tới đâu, và tự nói mình đã làm cách nào — nhớ lại, suy ra, loại trừ, hay đoán. <strong>Luôn kèm độ chắc chắn.</strong> Kết luận từ một bài test đơn lẻ đi kèm confidence thấp, và Nemo12 <strong>nói ra điều đó</strong> thay vì trình bày nó như sự thật. <strong>Khi chưa chắc thì đo thêm, không bắt học lại.</strong> Nếu mức vững thấp nhưng độ chắc chắn cũng thấp, hành động đúng là hỏi thêm một hai câu — không phải giao ngay một chương học lại.</p><h2 id="đieu-nay-khong-ha-thap-gia-tri-cua-ky-thi-​" tabindex="-1">Điều này không hạ thấp giá trị của kỳ thi <a href="#đieu-nay-khong-ha-thap-gia-tri-cua-ky-thi">​</a> <a class="header-anchor" href="#đieu-nay-khong-ha-thap-gia-tri-cua-ky-thi-​" aria-label="Permalink to &quot;Điều này không hạ thấp giá trị của kỳ thi [​](#đieu-nay-khong-ha-thap-gia-tri-cua-ky-thi)&quot;">​</a></h2><p>Kỳ thi vẫn quan trọng, và Nemo12 chuẩn bị cho kỳ thi rất nghiêm túc. Nhưng cần tách hai vai trò:</p><ul><li><strong>Kỳ thi là một cánh cửa</strong> — nó quyết định learner được vào đâu. Đây là thực tế, không tranh cãi.</li><li><strong>Kỳ thi là một phép đo</strong> — và ở vai trò này, nó là một phép đo nhiễu, một lần, trong điều kiện căng thẳng. Dùng nó cho vai trò đầu: hợp lý. Dùng nó làm cơ sở duy nhất để hiểu một đứa trẻ: quá mỏng cho một quyết định lớn. Câu hỏi đáng hỏi khi nhận một kết quả kém Trước khi phản ứng: <em>&quot;Đây là chuyện mới, hay đã thấy nhiều lần rồi?&quot;</em> Nếu là lần đầu — chờ thêm dữ liệu. Nếu đã lặp lại nhiều lần ở nhiều dạng — lúc đó mới là tín hiệu thật. Một bài test là một quan sát. Hiểu một đứa trẻ cần một chuỗi quan sát, và sự trung thực về việc mình còn chưa biết gì. <a href="/learner/cap-nhat">Hệ thống cập nhật hiểu biết ra sao →</a></li></ul>',11)])])}const k=t(g,[["render",r]]);export{s as __pageData,k as default};
